Ftcp=formula('R_i p+t_i=c; (R_i−R_1)p=t_1−t_i',{'R_i,R_1':'flange-to-base rotation matrices at observation i and reference observation 1','p':'fixed TCP position expressed in flange coordinates','t_i,t_1':'flange-origin positions in the base frame','c':'fixed reference-point position in the base frame','i':'observation index'},{'R_i,R_1,i':'dimensionless','p,t_i,t_1,c':'same length unit'},['Rigid tool, same physical contact point, sufficiently independent orientations; estimated poses may contain noise. Equations are an added derivation of the four-point procedure.'])
Fpoint=formula('p_A=R_AB p_B+t_AB; p_B=R_ABᵀ(p_A−t_AB)',{'p_A,p_B':'coordinates of the same point in frames A and B','R_AB':'proper rotation mapping B components into A','t_AB':'B-origin position expressed in A'},{'p_A,p_B,t_AB':'same length unit','R_AB':'dimensionless'},['Rigid frames, column vectors, R_ABᵀ R_AB=I.'])
Fhom=formula('T_A_B=[[R_AB,t_AB],[0,1]]; T_A_C=T_A_B T_B_C; T_B_A=[[R_ABᵀ,−R_ABᵀ t_AB],[0,1]]',{'T_A_B,T_B_C,T_A_C,T_B_A':'homogeneous transforms mapping the subscript-right frame to the subscript-left frame','R_AB':'proper B-to-A rotation','t_AB':'B-origin position in A','0':'one row of three zeros','1':'homogeneous scalar one'},{'rotation and homogeneous row':'dimensionless','translation entries':'same length unit'},['Column homogeneous vectors; transform order follows frame adjacency; rotation inverses are transposes.'])
Fcamera=formula('X=(u−cx)Z/fx; Y=(v−cy)Z/fy; p_C=(X,Y,Z)',{'u,v':'undistorted image column and row coordinates','cx,cy':'principal-point column and row','fx,fy':'positive focal lengths in pixel units','X,Y,Z':'camera-frame point components, with Z optical-axis depth','p_C':'camera-frame point'},{'u,v,cx,cy,fx,fy':'pixels','X,Y,Z,p_C':'same length unit'},['Pinhole/rectified model, positive valid Z, colour/depth registration or matching depth pixel. Z is not Euclidean range.'])
Fmom=formula('cx=m10/m00; cy=m01/m00',{'cx,cy':'image centroid column and row','m00':'nonzero zeroth spatial moment','m10,m01':'first column and row spatial moments'},{'cx,cy':'pixels','m00':'pixel² for an area contour','m10,m01':'pixel³ for an area contour'},['Area-moment convention, nonzero contour area; discrete binary-image moments have count-based units but the same ratios.'])
primary={'aruco':{'url':'https://docs.opencv.org/4.13.0/d5/dae/tutorial_aruco_detection.html','locator':'Markers/dictionaries and pose estimation: ordered corners, calibrated camera and physical side length, marker-to-camera pose.'},'calib':{'url':'https://docs.opencv.org/4.13.0/d9/d0c/group__calib3d.html','locator':'Pinhole projection, camera intrinsics and extrinsic transform convention.'},'hsv':{'url':'https://docs.opencv.org/4.13.0/df/d9d/tutorial_py_colorspaces.html','locator':'Ordinary 8-bit HSV hue 0–179 and BGR/RGB conversion distinctions.'},'c3':{'url':'https://github.com/ulsu-tech/c3bridge-server','locator':'README: remote Cross3 requests and responses, KukaVarProxy-compatible application protocol.'},'py':{'url':'https://github.com/linuxsand/py_openshowvar','locator':'README: Python port of OpenShowVar/KukaVarProxy client and variable read/write API.'},'cpp':{'url':'https://github.com/ImtsSrl/openshowvar','locator':'Repository implementation distinguishes original client from the separate Python port.'}}
issues=[]
def add(refs,key,title,stem,pairs,typ='conceptual',difficulty='easy',forms=None,steps=None,assumptions=None,conflict=None,evidence=None):
 q=b.add([r[0] for r in refs],key,title,stem,[x[0] for x in pairs],0,pairs[0][1],[x[1] for x in pairs],typ=typ,difficulty=difficulty,assumptions=assumptions,steps=steps or ([pairs[0][1]] if typ in ('numerical','derivation','code') else []),formulas=forms,conflict=conflict)
 random.Random(q['id']+':option-order').shuffle(q['options'])
 for c,r in zip(q['citations'],refs):
  c['kind']=r[1];c['locator']=f'Lecture L57, physical page {r[0]}, printed footer {r[0]-1802}: {r[2]}';c['role']=r[3] if len(r)>3 else ('conflict' if conflict else 'premise' if typ in ('scenario','numerical','derivation','code') else 'explicit')
 if conflict:
  q['conflictResolution'].update(sourceId='lectures',sourceSha256=SHA,physicalPages=[c['physicalPage'] for c in q['citations'] if c['role']=='conflict']);issues.append({'questionId':q['id'],'sourceClaim':conflict,'qualification':pairs[0][1],'physicalPages':q['conflictResolution']['physicalPages']})
 if evidence:q['primaryEvidence']=[dict(primary[x],checkedAt='2026-10-20T00:10:00+00:00') for x in evidence]
 q['difficultyRationale']='Direct recognition or a single short stated operation.' if difficulty=='easy' else 'Combines stated conventions, multiple operations or a realistic failure diagnosis.' if difficulty=='medium' else 'Multistage geometry and frame inversion with an additional tool offset.'
 b.save();return q
