add([(1808,'statement','Five KSS responsibilities including data and diagnostics.')],'kss-diagnosis','Select a KSS responsibility','A technician needs to inspect an error log and monitor variable values rather than create a new path. Which listed KSS function is the direct match?', [('Diagnostics and monitoring.','Logs, errors and monitored variables are grouped under diagnostics/monitoring.'),('Motion interpolation.','Interpolation generates motion between specified targets.'),('Tool-frame calibration data entry only.','Calibration data are configuration, not the requested error-log function.'),('Program archive management only.','Archiving handles program storage rather than live diagnostic values.')],typ='scenario')
