add([(1809,'statement','KRL logic, I/O and advanced-programming lists.')],'krl-groups','KRL construct categories','Which grouping follows the source?', [('FOR/WHILE: control flow; OUT/ANOUT: I/O; interrupts/triggers: advanced event handling.','These groups follow the displayed KRL categories.'),('FOR/WHILE: circular motion; OUT/ANOUT: frame calibration; interrupts/triggers: joint coordinates.','Looping, I/O and event constructs are incorrectly reclassified.'),('FOR/WHILE: camera calibration; OUT/ANOUT: contour moments; interrupts/triggers: colour thresholds.','Those are vision operations rather than the printed KRL groups.'),('FOR/WHILE: analogue outputs; OUT/ANOUT: repetition; interrupts/triggers: spline knots only.','This reverses loops and outputs and narrows event handling incorrectly.')],typ='match')
