add([(1816,'statement','Parallel-motion and uniform-gripping-force claim.','conflict')],'grip-qualification','Parallel motion and force','Which qualification is necessary for the source’s statement that parallel motion ensures uniform gripping force?', [('Parallel jaw kinematics alone do not establish equal contact forces; contact geometry and pneumatic/mechanical conditions also matter.','Motion symmetry is not by itself a force-balance measurement.'),('Parallel jaws necessarily generate equal friction coefficients on unlike surfaces.','Friction depends on contact materials and conditions.'),('Equal jaw travel fixes the gripping force independently of pressure.','Actuation pressure and mechanism loading still affect force.'),('Parallel jaws make object weight irrelevant to holding requirements.','The grasp must still support relevant external loads.')],conflict='The slide says parallel motion ensures uniform gripping force without specifying contact, pressure or mechanical symmetry conditions.')
add([(1815,'statement','Fingertips provide contact force.','premise'),(1816,'statement','Pneumatic parallel-jaw grasp.','premise')],'grip-calc','Added friction-grasp calculation','An added ideal vertical grasp uses two contacts, each with normal force N and friction coefficient 0.4. For mass 0.8 kg, g=10 m/s² and required safety factor 2 against slip, what minimum N per contact follows from 2μN≥2mg?', [('20 N.','The required friction is 16 N and 2×0.4×N≥16 gives N≥20 N per contact.'),('10 N.','This meets static weight without the stated factor of two.'),('40 N.','This omits one of the two contributing contacts.'),('8 N.','This equals the weight but does not account for friction coefficient or safety factor.')],typ='numerical',difficulty='medium',forms=[formula('2μN≥S mg',{'μ':'contact friction coefficient','N':'normal force at each of two contacts','S':'specified positive load safety factor','m':'object mass','g':'gravity magnitude'},{'μ,S':'dimensionless','N':'N','m':'kg','g':'m/s²'},['Added ideal equal-contact Coulomb-friction model, vertical static lift, no other support or acceleration; not a manufacturer rating.'])],steps=['Weight=8 N; design friction requirement=16 N.','Two contacts provide 0.8N of friction force; N≥20 N.'])
