add([(1820,'statement','Camera-calibration extrinsic parameters R,t.','premise'),(1830,'statement','Camera/marker/robot frame relation.','premise')],'extrinsic-scope','Checkerboard pose versus robot registration','A camera is calibrated from checkerboard images. Why is a camera-to-robot transform not automatically known?', [('The estimated checkerboard-to-camera poses need an additional relationship to the robot frame.','Per-view calibration extrinsics relate the observed board to the camera, not an unobserved robot base.'),('Camera calibration estimates only image colour and never any geometry.','It does estimate geometric projection parameters and board poses.'),('Every checkerboard origin is defined by convention to equal the robot root.','That physical registration must be established, not assumed.'),('A camera focal length is already a complete six-dimensional robot pose.','An intrinsic scalar/parameter set is not a rigid transform to the base.')],typ='scenario',difficulty='medium',evidence=['calib'])
add([(1820,'statement','Reprojection error minimization.','premise')],'reprojection-calc','Added image residual metric','Four checkerboard-corner Euclidean reprojection residual magnitudes are 1,2,2,1 pixels. Under the explicitly defined RMS over four corners, what is the error?', [('√2.5≈1.581 pixels.','The squared magnitudes sum to 10; divide by four and take the square root.'),('1.5 pixels.','This is the arithmetic mean of residual magnitudes, not RMS.'),('√10≈3.162 pixels.','This omits averaging by four corners.'),('2.5 pixels.','This is the mean squared magnitude before the square root.')],typ='numerical',forms=[formula('e_RMS=√[(1/N)Σi ||r_i||²]',{'e_RMS':'RMS Euclidean image residual per corner','N':'number of corners','r_i':'2D projected-minus-measured residual vector for corner i','i':'corner index'},{'e_RMS,r_i':'pixels','N,i':'dimensionless counts/indices'},['Added metric convention averages squared 2D magnitudes over corners, not separately over 2N scalar components.'])],steps=['Compute 1+4+4+1=10 pixel².','Divide by 4 and take the square root.'])
