add([(1823,'statement','Rotation and translation from marker pose.','premise'),(1832,'equation','Marker-to-camera and camera-to-object part of the frame chain.','premise')],'pnp-direction','Invert the estimated marker pose','Under the OpenCV convention p_C=R_CM p_M+t_CM, which expression maps an observed camera point into marker coordinates?', [('p_M=R_CMᵀ(p_C−t_CM).','First remove the camera-frame translation and then apply the inverse rotation.'),('p_M=R_CM p_C+t_CM.','This reuses the forward marker-to-camera transform in the wrong direction.'),('p_M=R_CMᵀ p_C−t_CM.','The translation must also be rotated when applying the inverse.'),('p_M=p_C−R_CM t_CM.','This omits rotation of the point and uses the wrong translation transformation.')],typ='derivation',difficulty='medium',forms=[Fpoint],steps=['Subtract t_CM from both sides.','Multiply by R_CMᵀ because R_CM is a proper rotation.'],evidence=['aruco'])
