add([(1826,'figure','Shape characteristics after contour extraction.','premise'),(1827,'statement','Geometric contour properties used to determine shape.','premise')],'shape-calc','Added contour descriptor','Define an added circularity score C=4πA/P² for area A and perimeter P. For A=100 pixel² and P=40 pixels, what is C?', [('π/4≈0.785.','Substitution gives 400π/1600=π/4.'),('π≈3.142.','This drops the factor of four in the squared perimeter denominator.'),('4π≈12.566.','This effectively omits the area/perimeter scaling.'),('1/4=0.25.','This omits π from the defined descriptor.')],typ='numerical',forms=[formula('C=4πA/P²',{'C':'added circularity descriptor','A':'contour area','P':'positive contour perimeter','π':'circle constant'},{'C,π':'dimensionless','A':'pixel²','P':'pixels'},['Added ideal contour descriptor; source names geometric shape features but does not prescribe this particular formula.'])],steps=['P²=1600; 4πA=400π.','Divide to obtain π/4.'])
