add([(1832,'equation','Common left factor T_W_R and tool-side factors.')],'cancel-world','Eliminate the world transform','From T_W_R T_R_F T_F_TCP T_TCP_O=T_W_R T_R_M T_M_C T_C_O, what valid step removes the common world transform?', [('Premultiply both sides by (T_W_R)⁻¹.','Matrix cancellation must occur on the same side as the common left factor.'),('Postmultiply both sides by (T_W_R)⁻¹ and delete every W label.','Right multiplication does not cancel a leftmost noncommuting factor.'),('Subtract T_W_R from both products entry by entry.','The transform is a multiplicative factor, not an additive term.'),('Divide each translation component by its world-frame coordinate.','Componentwise division is not rigid-transform inversion.')],typ='derivation',forms=[Fhom],steps=['Use (T_W_R)⁻¹ T_W_R=I on the left of both equations.'])
