add([(1834,'figure','Safe-height transit concept.','premise')],'clearance','Added clearance-budget calculation','For an added purely vertical clearance budget, the highest obstacle is at z=120 mm, required margin is 20 mm, and worst-case downward position error is 5 mm. What minimum nominal TCP transit height satisfies this scalar condition?', [('145 mm.','The worst-case actual height is nominal−5 and must be at least 120+20.'),('140 mm.','This includes the margin but not downward error.'),('135 mm.','This subtracts the error allowance instead of adding it.'),('125 mm.','This adds only the error allowance, omitting the requested margin.')],typ='numerical',forms=[formula('z_nom−e_down≥z_obstacle+m',{'z_nom':'nominal transit height','e_down':'nonnegative worst-case downward position error','z_obstacle':'highest obstacle height in the same coordinate frame','m':'required vertical clearance margin'},{'all heights/errors':'mm'},['Added scalar TCP-height model only; not a complete collision check for tool, carried object, links or motion path.'])],steps=['Require z_nom−5≥140.','Thus z_nom≥145 mm.'],assumptions=['Added scalar clearance model, not a hardware safety certification or complete route plan.'])
