add([(1839,'statement','Incorrect marker-size specification as an error source.','premise'),(1823,'statement','PnP marker pose estimation.','premise')],'marker-scale','Wrong marker size biases distance','For an added ideal pinhole view of a frontoparallel square, the true side is 40 mm but the pose solver is told 50 mm, with the same image corners and calibration. If true camera distance is 400 mm, what distance is inferred?', [('500 mm.','The inferred scale is multiplied by 50/40 under the declared geometry.'),('320 mm.','This applies the inverse scale ratio.'),('400 mm.','This incorrectly treats known physical marker size as irrelevant to metric scale.'),('410 mm.','This adds the side-length error directly to camera distance rather than scaling it.')],typ='numerical',difficulty='medium',forms=[formula('Z_est/Z_true=L_assumed/L_true',{'Z_est':'inferred optical distance','Z_true':'true optical distance','L_assumed':'physical side length supplied to the estimator','L_true':'actual side length'},{'all variables':'same length unit'},['Added noiseless frontoparallel pinhole geometry with unchanged image size and focal length.'])],steps=['Scale ratio=50/40=1.25.','Distance=1.25×400=500 mm.'],evidence=['aruco'])
