add([(1839,'statement','Small errors propagate through the system.','premise')],'error-budget','Independent noise versus worst-case bias','For an added scalar error model, independent zero-mean errors have standard deviations 2 mm and 3 mm. Their combined standard deviation is which value?', [('√13≈3.61 mm.','Independent variances add: 2²+3²=13 mm².'),('5 mm.','This is the sum of magnitudes, appropriate for a different worst-case-bound calculation rather than independent standard deviations.'),('1 mm.','Subtracting standard deviations does not combine independent errors.'),('13 mm.','13 is the variance in mm², not standard deviation.')],typ='numerical',forms=[formula('σ_total=√(σ1²+σ2²)',{'σ_total':'standard deviation of the sum','σ1,σ2':'standard deviations of the two scalar error contributions'},{'σ_total,σ1,σ2':'mm'},['Added independent zero-mean errors; no covariance term. Systematic errors need separate treatment.'])],steps=['Add variances 4+9=13 mm².','Take the square root.'])
